// origin: https://editor.p5js.org/AsukaMinato/sketches/EQl9Z4QG4  , rewrite by gemini 2.0 flash
// https://shadertoyunofficial.wordpress.com/2019/01/02/programming-tricks-in-shadertoy-glsl/
#define CS(a)        vec2( cos(a), sin(a) )

#define cmul(A,B) ( mat2( A, -(A).y, (A).x ) * (B) )  // by deMoivre formula
#define cmod(Z)     length(Z)
#define carg(Z)     atan( (Z).y, (Z).x )
#define pol2cart(U) ( (U).x * CS( (U).y ) )
#define cpow(Z,v)   pol2cart( vec2( pow(cmod(Z),v) , (v) * carg(Z) ) )
#define cdiv(A,B)   cmul( A, cinv(B) )
#define cinv(Z)   ( vec2( (Z).x, -(Z).y ) / dot(Z,Z) ) 


void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // 1. Coordinate Transformation: Shadertoy's fragCoord is in pixel coordinates.
    //    We need to map it to the complex plane (from -2 to 2 in both x and y).
    vec2 uv = (fragCoord / iResolution.xy) * 4.0 - 2.0; // Remapped to -2 to 2
	vec2 U = uv;

    vec2 z = uv; // Initial value

    // 3. Newton's Method Iteration:

    for (int i = 0; i < 30; i++) // Iteration count
    {
		//Complex function z^4 - 1
		vec2 z4 = cpow(z, 4.) - vec2(1., 0.);	
		//Derivative 4z^3
		vec2 dz = 4. * cpow(z, 3.);
        vec2 newZ = z - cdiv(z4, dz);  // z = z - f(z)/f'(z)
        if ( newZ == z )
        {
            z = newZ;
            break; // Exit if converged
        }
        z = newZ;
    }

    // 4. Color Mapping based on the converged point
    float r = sin(z.x);
    float g = sin(z.y);
    float b = length(z); // Magnitude (distance from origin)

    // 5. Output the color
    fragColor = vec4(r, g, b, 1.0);
}
